  // ID of the page that contains the block, from get_pages.
  pageid: number;
  // ID of the project that contains the page, from get_projects.
  projectid: number;
  // ID of the Zero Block (tplid 396), from get_page_records or add_record.
  recordid: number;
}): Promise<CallToolResult>; };
```

